 function repaintTrips(){const box=document.querySelector('#travel-trip-list');if(box)box.innerHTML=trips().filter(t=>(statusFilter==='all'||t.status===statusFilter)&&(!query||`${t.title} ${t.destination||''} ${t.note||''}`.toLowerCase().includes(query.toLowerCase()))).map(tripCard).join('')||empty('没有匹配的旅行');}
