 let html=field(kind==='travel_stop'?'地点名称':kind==='travel_booking'?'预订名称':'准备事项','title',x.title||'','text','required maxlength="120"')+`<div class="form-grid">${field('日期','date',x.date||dateDefault(t),'date',kind==='travel_check'?'required':`required min="${esc(t.startDate||t.date)}" max="${esc(t.endDate)}"`)}${field('当地时间（选填）','time',x.time||'','time')}</div>`;
 if(kind==='travel_stop')html+=select('地点类别','category',Object.entries(STOP_CATEGORIES),x.category||'attraction')+field('地址（选填）','address',x.address||'','text','maxlength="500"')+`<details class="travel-coordinates" ${finite(x.lat)?'open':''}><summary>地图坐标（选填）</summary><p>使用 WGS84 经纬度；没有坐标也能保存地点。点击选点后会加载 OpenStreetMap，地图服务将收到瓦片请求；不读取手机定位。</p><div class="form-grid"><div class="field"><label for="travel-lat">纬度</label><input id="travel-lat" name="lat" type="number" min="-90" max="90" step="any" value="${esc(x.lat??'')}"></div><div class="field"><label for="travel-lng">经度</label><input id="travel-lng" name="lng" type="number" min="-180" max="180" step="any" value="${esc(x.lng??'')}"></div></div><button type="button" class="btn" data-action="travel-form-map">${icon('map',16)}在地图上选点</button><div id="travel-form-map" class="travel-form-map" hidden></div></details>`+field('当天顺序','position',x.position??0,'number','min="0" max="10000" step="1"');
 if(kind==='travel_booking')html+=select('预订类型','bookingType',Object.entries(BOOKING_TYPES),x.bookingType||'hotel')+select('预订状态','status',[['planned','待确认'],['confirmed','已确认'],['cancelled','已取消']],x.status||'confirmed')+field('结束 / 退房日期（选填）','endDate',x.endDate||'','date')+field('位置 / 路线（选填）','location',x.location||'','text','maxlength="250"')+field('确认号（选填）','confirmationCode',x.confirmationCode||'','text','maxlength="120"')+`<div class="form-grid">${field('预订金额（选填）','price',x.price??'','number','min="0" max="1000000000000" step="any"')}${select('币种','currency',[['CNY','CNY 人民币'],['USD','USD 美元'],['HKD','HKD 港币'],['EUR','EUR 欧元'],['JPY','JPY 日元'],['GBP','GBP 英镑']],x.currency||'CNY')}</div>`+field('预订链接（选填）','referenceUrl',x.referenceUrl||'','url','maxlength="2000" placeholder="https://…"');
